// Tidy up settings pasted into a hosting dashboard: trim spaces and stray
// surrounding quotes, accept True/TRUE/yes, and accept +91 / spaces in mobiles.
for(const k of ['SERVER_ENABLED','GOOGLE_SHEETS_ID','GOOGLE_SERVICE_ACCOUNT_JSON','SESSION_SECRET','ADMIN_MOBILE','ADMIN_PASSWORD','OPERATIONS_ENABLED','POLICY_APPROVED','FIREWORKS_LEGAL_CLEARANCE','TRUST_PROXY','GOOGLE_DRIVE_FOLDER_ID']){let v=process.env[k];if(typeof v!=='string')continue;v=v.trim();if(/^(['"]).*\1$/s.test(v)&&k!=='GOOGLE_SERVICE_ACCOUNT_JSON')v=v.slice(1,-1).trim();if(/^(SERVER_ENABLED|OPERATIONS_ENABLED|POLICY_APPROVED|FIREWORKS_LEGAL_CLEARANCE|TRUST_PROXY)$/.test(k)&&/^(true|yes|1|on)$/i.test(v))v='true';if(k==='ADMIN_MOBILE')v=v.replace(/[\s-]/g,'').replace(/^(\+91|0091|91(?=\d{10}$)|0(?=\d{10}$))/,'');if(k==='GOOGLE_SHEETS_ID'){const m=v.match(/\/d\/([a-zA-Z0-9_-]{20,})/);if(m)v=m[1]}if(v)process.env[k]=v;else delete process.env[k]}
function friendlyGoogleError(err){const m=String(err?.message||err||'Connection setup failed');let email='';try{email=JSON.parse(process.env.GOOGLE_SERVICE_ACCOUNT_JSON||'{}').client_email||''}catch{}
 if(/has not been used in project|is disabled|SERVICE_DISABLED|accessNotConfigured/i.test(m))return 'Google Sheets API is turned off for this Google Cloud project. Open console.cloud.google.com → APIs & Services → Enable APIs, enable "Google Sheets API", wait 2 minutes and refresh.';
 if(/permission|PERMISSION_DENIED|403/i.test(m))return `The Google Sheet is not shared with the service account. In the sheet click Share and add ${email||'the service account email'} as Editor.`;
 if(/not found|NOT_FOUND|404/i.test(m))return 'Google Sheet not found. Check GOOGLE_SHEETS_ID (the code between /d/ and /edit in the sheet URL).';
 if(/invalid_grant|DECODER|PEM|private key|invalid_client|account not found/i.test(m))return 'The service account key is not valid. Create a new JSON key and paste the whole file into GOOGLE_SERVICE_ACCOUNT_JSON.';
 return m.slice(0,240)}
/** Which settings are present (never their values), for the setup checklist. */
function setupCheck(){const e=process.env,c={};c.SERVER_ENABLED=e.SERVER_ENABLED==='true'?'ok':e.SERVER_ENABLED?'must be true':'missing';c.GOOGLE_SHEETS_ID=!e.GOOGLE_SHEETS_ID?'missing':/^[a-zA-Z0-9_-]{20,}$/.test(e.GOOGLE_SHEETS_ID)?'ok':'looks wrong (use the code between /d/ and /edit)';{const j=e.GOOGLE_SERVICE_ACCOUNT_JSON;if(!j)c.GOOGLE_SERVICE_ACCOUNT_JSON=e.GOOGLE_APPLICATION_CREDENTIALS?'ok':'missing';else{try{const o=JSON.parse(j);c.GOOGLE_SERVICE_ACCOUNT_JSON=o.client_email&&o.private_key?'ok':'JSON is missing client_email or private_key'}catch{c.GOOGLE_SERVICE_ACCOUNT_JSON='not valid JSON (paste the whole file, including { and })'}}}c.SESSION_SECRET=!e.SESSION_SECRET?'missing':e.SESSION_SECRET.length<32?'too short (needs 32+ characters)':'ok';c.ADMIN_MOBILE=!e.ADMIN_MOBILE?'missing':/^[6-9]\d{9}$/.test(e.ADMIN_MOBILE)?'ok':'must be a 10-digit Indian mobile';c.ADMIN_PASSWORD=e.ADMIN_PASSWORD_HASH?'ok':process.env.__ADMIN_PW_SHORT?'too short (needs 10+ characters)':'missing';return c}
const app=express(),port=Number(process.env.PORT||3000),enabled=process.env.SERVER_ENABLED==='true';
const operationsAllowed=()=>process.env.OPERATIONS_ENABLED==='true'&&process.env.POLICY_APPROVED==='true';
const legallyCleared=()=>operationsAllowed()&&process.env.FIREWORKS_LEGAL_CLEARANCE==='true';
const now=()=>new Date().toISOString(),id=p=>`${p}-${crypto.randomBytes(7).toString('hex').toUpperCase()}`;
const publicPath=path.join(path.dirname(fileURLToPath(import.meta.url)),'../public');
const csrfMethods=new Set(['POST','PUT','PATCH','DELETE']);
app.disable('x-powered-by');app.set('trust proxy',(process.env.TRUST_PROXY==='true'||process.env.VERCEL)?1:false);
// Wait for the Google Sheet connection before handling API calls (matters on
// Vercel, where each cold start connects again). Retry a failed connection
// at most every 30 seconds so a fixed setting takes effect without a redeploy.
let ready=Promise.resolve(),lastInitTry=0;
function startInit(){lastInitTry=Date.now();sheetInitError=null;ready=init().catch(err=>{sheetInitError=err;console.error('Google integration not ready:',err.message)});return ready}
app.use('/api',async(req,res,next)=>{if(enabled&&!store&&sheetInitError&&Date.now()-lastInitTry>30000)startInit();await ready;next()});
app.use(helmet({contentSecurityPolicy:false}));app.use(express.json({limit:'100kb'}));app.use(cookieParser());
app.use('/api',rateLimit({windowMs:15*60*1000,limit:350,standardHeaders:'draft-7',legacyHeaders:false}));
app.use((req,res,next)=>{if(csrfMethods.has(req.method)&&req.path.startsWith('/api/')){const origin=req.get('origin');const host=req.get('x-forwarded-host')||req.get('host');if(origin){let o;try{o=new URL(origin)}catch{return res.status(403).json({error:'Invalid request origin'})}if(o.host!==host)return res.status(403).json({error:'Cross-origin request blocked'})}if(req.get('x-jga-request')!=='1')return res.status(403).json({error:'Missing request-verification header'})}next()});
const json=(res,code,data)=>res.status(code).json(data);
const invalid=(message,code=400)=>{const ex=new Error(message);ex.status=code;throw ex};
const asyncRoute=f=>(req,res,next)=>Promise.resolve().then(()=>f(req,res)).catch(next);
const passHash=(password,salt)=>crypto.scryptSync(password,salt,64).toString('hex');
const passVerify=(password,salt,hash)=>{if(!salt||!hash||typeof password!=='string')return false;const left=Buffer.from(passHash(password,salt),'hex'),right=Buffer.from(hash,'hex');return left.length===right.length&&crypto.timingSafeEqual(left,right)};
const validPin=pin=>typeof pin==='string'&&/^[0-9]{4}$/.test(pin);
// Additional per-number rate limit (the existing per-IP login limit also applies).
const pinAttempts=rateLimit({windowMs:15*60*1000,limit:5,standardHeaders:'draft-7',legacyHeaders:false,keyGenerator:req=>String(req.body?.mobile||'unknown')});
const secret=process.env.SESSION_SECRET||'';
// Admin password: either ADMIN_PASSWORD (plain, kept only in the host's secret
// environment and hashed in memory at start-up) or a pre-computed SALT/HASH pair.
if(process.env.ADMIN_PASSWORD&&!process.env.ADMIN_PASSWORD_HASH){if(process.env.ADMIN_PASSWORD.length<10){process.env.__ADMIN_PW_SHORT='1';console.error('ADMIN_PASSWORD must be at least 10 characters; admin login disabled')}else{const salt=crypto.randomBytes(16).toString('hex');process.env.ADMIN_PASSWORD_SALT=salt;process.env.ADMIN_PASSWORD_HASH=crypto.scryptSync(process.env.ADMIN_PASSWORD,salt,64).toString('hex')}delete process.env.ADMIN_PASSWORD}
function makeToken(payload){const d=Buffer.from(JSON.stringify({...payload,exp:Date.now()+1000*60*60*12})).toString('base64url');const sig=crypto.createHmac('sha256',secret).update(d).digest('base64url');return `${d}.${sig}`}
function fromToken(token){if(!secret||!token)return null;let [d,sig]=token.split('.');if(!d||!sig)return null;const correct=crypto.createHmac('sha256',secret).update(d).digest('base64url');if(sig.length!==correct.length||!crypto.timingSafeEqual(Buffer.from(sig),Buffer.from(correct)))return null;let obj;try{obj=JSON.parse(Buffer.from(d,'base64url').toString('utf8'))}catch{return null}return obj.exp>Date.now()?obj:null}
async function auth(req,res,next){
 const token=fromToken(req.cookies?.jga_session);
 if(!token)return json(res,401,{error:'Please log in'});
 if(token.role==='admin'){req.identity=token;return next()}
 if(!store)return json(res,503,{error:'Authentication backend is not configured'});
 try{
  const account=await store.find('Auth_Users',token.id);
  if(!account||String(account.active)==='false'||String(account.authRev||'')!==String(token.authRev||''))return json(res,401,{error:'Session expired. Please log in again'});
  if(String(account.mustChangePassword)==='true'&&!['/api/auth/change-password','/api/auth/logout','/api/me'].includes(req.path))return json(res,403,{error:'Change your temporary password before continuing'});
  req.identity={...token,role:account.role,customerId:account.customerId||''};return next();
 }catch(err){return next(err)}
}
const role=(...roles)=>(req,res,next)=>roles.includes(req.identity.role)?next():json(res,403,{error:'Access denied'});
const upload=multer({storage:multer.memoryStorage(),limits:{fileSize:10*1024*1024,files:1}});
let store=null,drive=null;let sheetInitError=null;
async function init(){if(!enabled)return;if(!process.env.GOOGLE_SHEETS_ID||secret.length<32)throw Error('Missing GOOGLE_SHEETS_ID or 32-character SESSION_SECRET');const s=await SheetStore.connect();await s.setup();if(!(await s.list('Pricing_Master')).length){for(const tier of DEFAULT_BOX_TIERS)await s.insert('Pricing_Master',{...tier,updatedAt:now()})}store=s;if(process.env.GOOGLE_DRIVE_FOLDER_ID){const authGoogle=googleAuth(['https://www.googleapis.com/auth/drive.file']);drive=google.drive({version:'v3',auth:await authGoogle.getClient()})}console.log('Google Sheet connected and worksheets ready');}
const requireStore=(req,res,next)=>store?next():json(res,503,{error:'Connected server not configured; demo is available.'});
async function settings(){const conf=defaultWindows(),rows=await store.list('Settings');for(const r of rows){if(r.key.startsWith('window.')){const k=r.key.slice(7);if(conf[k]){try{let value=JSON.parse(r.value);conf[k]={...conf[k],...value}}catch{}}}}return conf}
async function gate(kind){if(!operationsAllowed())invalid('Operations are disabled until approved terms and policy clearance are configured',423);if(kind==='order'&&!legallyCleared())invalid('Ordering is disabled pending applicable legal clearance',423);if(!windowOpen(await settings(),kind))invalid(`${kind} window is closed`,423)}
async function audit(actor,action,entity,entityId,before='',after='',reason=''){await store.insert('Audit_Log',{id:id('AUD'),actor,action,entity,entityId,before:typeof before==='string'?before:JSON.stringify(before),after:typeof after==='string'?after:JSON.stringify(after),reason,createdAt:now()})}
async function accountScoped(identity,customerId){if(identity.role==='admin')return true;if(identity.customerId===customerId)return true;if(identity.role==='leader'){const cust=await store.find('Customers',customerId);if(!cust||!cust.groupId)return false;const g=await store.find('Groups',cust.groupId);return Boolean(g&&g.leaderCustomerId===identity.customerId)}return false}
async function orderScoped(req,order){if(req.identity.role==='admin'||order.accountId===req.identity.id)return true;return accountScoped(req.identity,order.customerId)}
async function financial(order){const all=await Promise.all([store.list('Order_Boxes'),store.list('Order_Uploads'),store.list('Pricing_Master'),store.list('Payments')]);const [boxRows,uploads,pricing,payments]=all;const customer=order.kind==='EMI'?await store.find('Customers',order.customerId):null;const account=customer?paymentAccount(customer,payments):null;const extraPaid=payments.filter(p=>p.orderId===order.id&&p.kind==='EXTRA'&&p.status==='Verified').reduce((sum,p)=>sum+Number(p.amount),0);return computeOrder(order,boxRows.filter(b=>b.orderId===order.id),uploads.filter(u=>u.orderId===order.id),pricing,account,extraPaid)}
async function refreshCustomerOrderFinance(customerId){const orders=(await store.list('Orders')).filter(o=>o.customerId===customerId);for(const o of orders){const f=await financial(o);await store.update('Orders',o.id,{financialStatus:f.financialStatus,updatedAt:now()})}}
app.get('/api/status',asyncRoute(async(req,res)=>json(res,200,{site:'Jay Ganesh Agency — Diwali 2027',previewOnly:!store,operationsAllowed:operationsAllowed(),legalClearanceConfigured:legallyCleared(),sheetsConnected:!!store,serverEnabled:enabled,adminConfigured:Boolean(process.env.ADMIN_MOBILE&&process.env.ADMIN_PASSWORD_HASH),timezone:'Asia/Kolkata',setup:setupCheck(),serviceAccountEmail:(()=>{try{return JSON.parse(process.env.GOOGLE_SERVICE_ACCOUNT_JSON||'{}').client_email||undefined}catch{return undefined}})(),windows:store?await settings():defaultWindows(),error:sheetInitError?friendlyGoogleError(sheetInitError):undefined})));
app.post('/api/auth/login',rateLimit({windowMs:15*60*1000,limit:8,standardHeaders:'draft-7',legacyHeaders:false}),pinAttempts,requireStore,asyncRoute(async(req,res)=>{const {mobile}=req.body||{};const password=req.body?.pin??req.body?.password;if(!/^[6-9]\d{9}$/.test(String(mobile||''))||typeof password!=='string')invalid('Invalid login',401);let user;if(mobile===process.env.ADMIN_MOBILE&&process.env.ADMIN_PASSWORD_HASH&&process.env.ADMIN_PASSWORD_SALT){if(!passVerify(password,process.env.ADMIN_PASSWORD_SALT,process.env.ADMIN_PASSWORD_HASH))invalid('Invalid login',401);user={id:'MAIN-ADMIN',role:'admin',customerId:''}}else{user=(await store.list('Auth_Users')).find(u=>u.mobile===mobile);if(!user||!validPin(password)||!passVerify(password,user.passwordSalt,user.passwordHash))invalid('Invalid login',401);if(String(user.active)==='false')invalid('Your registration is awaiting Main Admin approval',403)}const token=makeToken({id:user.id,role:user.role,customerId:user.customerId||'',authRev:user.authRev||''});res.cookie('jga_session',token,{httpOnly:true,secure:process.env.NODE_ENV==='production',sameSite:'strict',path:'/',maxAge:12*60*60*1000});json(res,200,{loggedIn:true,role:user.role,customerId:user.customerId||'',mustChangePassword:String(user.mustChangePassword)==='true'})}));
app.post('/api/auth/logout',auth,(req,res)=>{res.clearCookie('jga_session',{path:'/'});json(res,200,{loggedOut:true})});
app.get('/api/me',auth,asyncRoute(async(req,res)=>{const {id,role,customerId}=req.identity;const customer=customerId&&role!=='direct'?await store.find('Customers',customerId):null;return json(res,200,{id,role,customerId,customer})}));
app.post('/api/auth/change-password',requireStore,auth,asyncRoute(async(req,res)=>{const currentPassword=req.body?.currentPin??req.body?.currentPassword,newPassword=req.body?.newPin??req.body?.newPassword;if(!validPin(newPassword))invalid('New PIN must contain exactly 4 digits');if(req.identity.role==='admin')invalid('Change Main Admin password through deployment secrets',403);await store.serial(async()=>{const row=await store.find('Auth_Users',req.identity.id);if(!row||!passVerify(currentPassword,row.passwordSalt,row.passwordHash))invalid('Incorrect existing password',403);const salt=crypto.randomBytes(16).toString('hex');await store.update('Auth_Users',row.id,{passwordSalt:salt,passwordHash:passHash(newPassword,salt),authRev:crypto.randomBytes(12).toString('hex'),mustChangePassword:false});await audit(req.identity.id,'CHANGE_PASSWORD','Auth_Users',row.id,'','password changed')});res.clearCookie('jga_session',{path:'/'});json(res,200,{changed:true,loginAgain:true})}));
app.post('/api/registration',requireStore,asyncRoute(async(req,res)=>{await gate('registration');const {name,mobile,reference,emi,comments,acceptedTerms}=req.body||{};const password=req.body?.pin??req.body?.password;const monthly=Number(emi);if(typeof name!=='string'||name.trim().length<2||name.length>90||!(/^[6-9]\d{9}$/).test(String(mobile||''))||!reference||!isMonthlyEmi(monthly)||acceptedTerms!==true||!validPin(password))invalid('Invalid registration details, 4-digit PIN or terms not accepted');await store.serial(async()=>{const [requests,customers,authUsers]=await Promise.all([store.list('Registration_Requests'),store.list('Customers'),store.list('Auth_Users')]);if(requests.some(r=>r.mobile===mobile&&r.status!=='Rejected')||customers.some(x=>x.mobile===mobile)||authUsers.some(x=>x.mobile===mobile))invalid('Mobile number is already registered',409);const salt=crypto.randomBytes(16).toString('hex');await store.insert('Auth_Users',{id:id('USR'),mobile,passwordSalt:salt,passwordHash:passHash(password,salt),role:'customer',customerId:'',active:false,createdAt:now(),authRev:crypto.randomBytes(12).toString('hex'),mustChangePassword:false});await store.insert('Registration_Requests',{id:id('REQ'),name:name.trim(),mobile,reference:String(reference).trim(),emi:monthly,comments:String(comments||'').slice(0,500),acceptedTerms:true,status:'Pending Approval',createdAt:now()})});json(res,201,{status:'Pending Approval',message:'Use your registered mobile and chosen 4-digit PIN after Main Admin approval; no OTP is required'})}));
