app.post('/api/admin/registrations/:id/approve',requireStore,auth,role('admin'),asyncRoute(async(req,res)=>{let approved;await store.serial(async()=>{const r=await store.find('Registration_Requests',req.params.id);if(!r||r.status!=='Pending Approval')invalid('Request is not pending',409);if((await store.list('Customers')).some(c=>c.mobile===r.mobile))invalid('Customer already exists',409);const customerId=id('JGA27');const account=(await store.list('Auth_Users')).find(u=>u.mobile===r.mobile&&String(u.active)==='false');if(!account)invalid('No password account exists for this registration. Main Admin must complete a verified legacy account setup before approval.',409);await store.insert('Customers',{id:customerId,name:r.name,mobile:r.mobile,reference:r.reference,emi:r.emi,groupId:'',bonusApproved:false,status:'Approved',createdAt:now()});await store.update('Auth_Users',account.id,{customerId,active:true});for(let i=1;i<=9;i++)await store.insert('EMI_Schedule',{id:id('EMI'),customerId,installment:i,dueAmount:i===1?Number(r.emi)*1.5:r.emi,dueDate:''});await store.update('Registration_Requests',r.id,{status:'Approved',reviewedAt:now(),reviewedBy:req.identity.id});await audit(req.identity.id,'APPROVE_REGISTRATION','Customer',customerId,'',r);approved={customerId}});json(res,200,{...approved,message:'Approved; customer logs in with the same mobile number and 4-digit PIN chosen at registration.'})}));
app.post('/api/admin/registrations/:id/reject',requireStore,auth,role('admin'),asyncRoute(async(req,res)=>{await store.serial(async()=>{const r=await store.find('Registration_Requests',req.params.id);if(!r||r.status!=='Pending Approval')invalid('Request not pending',409);await store.update('Registration_Requests',r.id,{status:'Rejected',reviewedAt:now(),reviewedBy:req.identity.id});await audit(req.identity.id,'REJECT_REGISTRATION','Registration',r.id,r.status,'Rejected',String(req.body?.reason||''))});json(res,200,{status:'Rejected'})}));
