app.post('/api/admin/accounts/legacy-provision',requireStore,auth,role('admin'),asyncRoute(async(req,res)=>{const mobile=String(req.body?.mobile||''),reason=String(req.body?.reason||'').trim();if(!/^[6-9]\d{9}$/.test(mobile)||reason.length<10)invalid('Mobile and identity-verification reason (at least 10 characters) required');let result;await store.serial(async()=>{const [accounts,customers,requests]=await Promise.all([store.list('Auth_Users'),store.list('Customers'),store.list('Registration_Requests')]);if(accounts.some(a=>a.mobile===mobile))invalid('Password account already exists; use the reset-password workflow instead',409);const customer=customers.find(c=>c.mobile===mobile&&c.status==='Approved');const registration=requests.find(r=>r.mobile===mobile&&r.status==='Pending Approval');if(!customer&&!registration)invalid('No approved or pending registration with this mobile number',404);const temporaryPassword=String(crypto.randomInt(0,10000)).padStart(4,'0'),salt=crypto.randomBytes(16).toString('hex');await store.insert('Auth_Users',{id:id('USR'),mobile,passwordSalt:salt,passwordHash:passHash(temporaryPassword,salt),role:'customer',customerId:customer?.id||'',active:!!customer,createdAt:now(),authRev:crypto.randomBytes(12).toString('hex'),mustChangePassword:true});await audit(req.identity.id,'LEGACY_ACCOUNT_PROVISION','Auth_Users',mobile,'','Temporary account created after identity review',reason);result={mobile,customerId:customer?.id||'',pendingApproval:!customer,temporaryPin:temporaryPassword,oneTimeDisplay:true}});json(res,201,result)}));
