app.post('/api/admin/accounts/:customerId/reset-password',requireStore,auth,role('admin'),asyncRoute(async(req,res)=>{const reason=String(req.body?.reason||'').trim();if(reason.length<10)invalid('Record how identity was verified and why reset is required (at least 10 characters)');let result;await store.serial(async()=>{const customer=await store.find('Customers',req.params.customerId);if(!customer)invalid('Customer not found',404);const account=(await store.list('Auth_Users')).find(u=>u.customerId===customer.id);if(!account)invalid('Account not yet provisioned; contact system administrator',409);const temporaryPassword=String(crypto.randomInt(0,10000)).padStart(4,'0');const salt=crypto.randomBytes(16).toString('hex');await store.update('Auth_Users',account.id,{passwordSalt:salt,passwordHash:passHash(temporaryPassword,salt),authRev:crypto.randomBytes(12).toString('hex'),mustChangePassword:true});await audit(req.identity.id,'ADMIN_RESET_PASSWORD','Auth_Users',account.id,'','Password reset after identity review',reason);result={customerId:customer.id,temporaryPin:temporaryPassword,oneTimeDisplay:true}});json(res,200,result)}));
app.post('/api/direct-signup',requireStore,asyncRoute(async(req,res)=>{await gate('order');const {name,mobile}=req.body||{};const password=req.body?.pin??req.body?.password;if(!name||!/^[6-9]\d{9}$/.test(mobile||'')||!validPin(password))invalid('Name, valid mobile and 4-digit PIN required');let created;await store.serial(async()=>{if((await store.list('Auth_Users')).some(x=>x.mobile===mobile)||(await store.list('Customers')).some(x=>x.mobile===mobile))invalid('Mobile number already registered',409);const contact=id('DIRECT'),salt=crypto.randomBytes(16).toString('hex');await store.insert('Direct_Order_Contacts',{id:contact,name:String(name).trim(),mobile,createdAt:now()});await store.insert('Auth_Users',{id:id('USR'),mobile,passwordSalt:salt,passwordHash:passHash(password,salt),role:'direct',customerId:contact,active:true,createdAt:now()});created={directBuyerId:contact}});json(res,201,created)}));
app.get('/api/groups',requireStore,auth,asyncRoute(async(req,res)=>{const groups=await store.list('Groups');const filtered=req.identity.role==='admin'?groups:groups.filter(g=>g.leaderCustomerId===req.identity.customerId||(req.identity.role==='customer'&&req.identity.customerId));if(req.identity.role==='customer'){const c=await store.find('Customers',req.identity.customerId);return json(res,200,{groups:filtered.filter(x=>x.id===c?.groupId)})}return json(res,200,{groups:filtered})}));
