app.post('/api/leader/payments/:id/review',requireStore,auth,role('leader'),asyncRoute(async(req,res)=>{const decision=String(req.body?.decision||'');if(!['acknowledge','reject'].includes(decision))invalid('Decision must be acknowledge or reject');await store.serial(async()=>{const p=await store.find('Payments',req.params.id);if(!p||p.kind!=='EMI'||p.status!=='Awaiting Leader')invalid('EMI payment is not awaiting Group Leader review',409);const c=await store.find('Customers',p.customerId),g=c?.groupId&&await store.find('Groups',c.groupId);if(!g||g.leaderCustomerId!==req.identity.customerId||p.recipientId!==g.leaderCustomerId)invalid('Payment is outside your assigned group or has an incorrect recipient',403);if(String(p.submittedBy)===String(req.identity.id))invalid('Cannot acknowledge your own entry',403);const status=decision==='acknowledge'?'Leader Verified':'Rejected';await store.update('Payments',p.id,{status,leaderApprovedBy:decision==='acknowledge'?req.identity.id:'',leaderApprovedAt:decision==='acknowledge'?now():'',leaderRejectedAt:decision==='reject'?now():''});await audit(req.identity.id,'LEADER_REVIEW_PAYMENT','Payment',p.id,'Awaiting Leader',status)});json(res,200,{status:decision==='acknowledge'?'Leader Verified':'Rejected',message:decision==='acknowledge'?'Include this entry in the next group collection; it is not yet credited':'Submission rejected'})}));
