app.post('/api/orders',requireStore,auth,role('customer','direct'),asyncRoute(async(req,res)=>{await gate('order');const kind=req.identity.role==='direct'?'DIRECT':'EMI';let created;await store.serial(async()=>{if((await store.list('Orders')).some(o=>o.accountId===req.identity.id))invalid('Only one order per customer is permitted',409);const customerId=req.identity.customerId;if(kind==='EMI'&&!await store.find('Customers',customerId))invalid('Approved customer account required',403);created={id:id('ORD'),accountId:req.identity.id,customerId,kind,type:'Only Box',status:'Draft',listCount:0,createdAt:now(),updatedAt:now(),financialStatus:'Pricing Pending'};await store.insert('Orders',created);await audit(req.identity.id,'CREATE_ORDER','Order',created.id,'',created)});json(res,201,created)}));
