app.patch('/api/orders/:id/draft',requireStore,auth,role('customer','direct'),asyncRoute(async(req,res)=>{await gate('order');await store.serial(async()=>{const o=await store.find('Orders',req.params.id);if(!o||o.accountId!==req.identity.id)invalid('Not your order',403);if(o.status!=='Draft')invalid('This order is locked',423);const {type,boxes,listCount}=req.body||{};if(!VALID_ORDER_TYPES.includes(type))invalid('Invalid order type');if(!Number.isInteger(Number(listCount))||listCount<0||listCount>10)invalid('List count must be 0–10');if(type==='Only Box'&&listCount!==0||type!=='Only Box'&&Number(listCount)<1)invalid('List count inconsistent with order type');if(!Array.isArray(boxes)||boxes.length>50)invalid('Invalid boxes');const uploaded=(await store.list('Order_Uploads')).filter(u=>u.orderId===o.id);if(type==='Only Box'&&uploaded.length)invalid('Existing PDF uploads must be handled by Main Admin before changing to Only Box',409);if(type!=='Only Box'&&uploaded.length>Number(listCount))invalid('Existing PDFs exceed requested list count',409);let master=await store.list('Pricing_Master');for(const b of boxes){if(!master.find(p=>p.id===b.pricingId&&String(p.active)!=='false')||!Number.isSafeInteger(b.quantity)||b.quantity<0)invalid('Invalid box selection')};const existing=(await store.list('Order_Boxes')).filter(x=>x.orderId===o.id);for(const row of existing)await store.update('Order_Boxes',row.id,{quantity:0});for(const b of boxes){const old=existing.find(x=>x.pricingId===b.pricingId);if(old)await store.update('Order_Boxes',old.id,{quantity:b.quantity});else await store.insert('Order_Boxes',{id:id('OB'),orderId:o.id,pricingId:b.pricingId,quantity:b.quantity})}await store.update('Orders',o.id,{type,listCount,updatedAt:now()});await audit(req.identity.id,'SAVE_ORDER_DRAFT','Order',o.id,'',{type,listCount,boxes});await refreshCustomerOrderFinance(o.customerId)});json(res,200,{saved:true})}));
app.post('/api/orders/:id/upload',requireStore,auth,role('customer','direct'),upload.single('pdf'),asyncRoute(async(req,res)=>{if(!drive)invalid('PDF uploads are not configured (GOOGLE_DRIVE_FOLDER_ID missing)',503);await gate('order');const o=await store.find('Orders',req.params.id);if(!o||o.accountId!==req.identity.id)invalid('Not your order',403);if(o.status!=='Draft')invalid('Locked order uploads cannot be changed',423);if(o.type==='Only Box')invalid('This order does not include a PDF list');if(!req.file||req.file.buffer.subarray(0,5).toString()!=='%PDF-'||req.file.mimetype!=='application/pdf')invalid('A valid PDF file is required');const existing=(await store.list('Order_Uploads')).filter(x=>x.orderId===o.id);if(existing.length>=Number(o.listCount))invalid('Maximum number of PDFs reached',409);const fileName=`${o.id}_${id('LIST')}.pdf`;const created=await drive.files.create({requestBody:{name:fileName,parents:[process.env.GOOGLE_DRIVE_FOLDER_ID],description:`Private customer PDF for order ${o.id}`},media:{mimeType:'application/pdf',body:Readable.from(req.file.buffer)},fields:'id,name',supportsAllDrives:true});const uploadRow={id:id('FILE'),orderId:o.id,driveFileId:created.data.id,filename:fileName,originalFilename:path.basename(req.file.originalname).slice(0,150),advertisedListValue:'',status:'Pending',createdAt:now()};await store.serial(async()=>{await store.insert('Order_Uploads',uploadRow);await audit(req.identity.id,'UPLOAD_ORDER_PDF','Order',o.id,'',fileName)});json(res,201,{id:uploadRow.id,filename:fileName,status:'Pending'})}));
app.post('/api/admin/uploads/:id/price',requireStore,auth,role('admin'),asyncRoute(async(req,res)=>{const advertised=Number(req.body?.advertisedListValue);if(!money(advertised)||advertised<0)invalid('Approved list value must be non-negative');await store.serial(async()=>{const x=await store.find('Order_Uploads',req.params.id);if(!x)invalid('List not found',404);await store.update('Order_Uploads',x.id,{advertisedListValue:advertised,status:'Approved',approvedBy:req.identity.id,approvedAt:now()});await audit(req.identity.id,'APPROVE_PDF_PRICE','Order_Upload',x.id,x.advertisedListValue,advertised,String(req.body?.reason||''));const o=await store.find('Orders',x.orderId);if(o){const f=await financial(o);await store.update('Orders',o.id,{financialStatus:f.financialStatus,updatedAt:now()})}});json(res,200,{approved:true})}));
app.post('/api/orders/:id/lock',requireStore,auth,role('customer','direct'),asyncRoute(async(req,res)=>{await gate('order');let status;await store.serial(async()=>{const o=await store.find('Orders',req.params.id);if(!o||o.accountId!==req.identity.id)invalid('Not your order',403);if(o.status!=='Draft')invalid('Already locked',409);const boxes=(await store.list('Order_Boxes')).filter(x=>x.orderId===o.id&&Number(x.quantity)>0),uploads=(await store.list('Order_Uploads')).filter(x=>x.orderId===o.id);if(o.type!=='Only List'&&!boxes.length)invalid('Select at least one box');if(o.type!=='Only Box'&&uploads.length!==Number(o.listCount))invalid('Upload all required PDF lists');const f=await financial(o);if(!f.pricingPending&&f.unusedCredit>0)invalid('Add more items to utilize full scheme credit before locking',409);status=f.pricingPending?'Pricing Pending':'Validated';await store.update('Orders',o.id,{status:'Locked',lockedAt:now(),updatedAt:now(),financialStatus:status});await audit(req.identity.id,'LOCK_ORDER','Order',o.id,'Draft','Locked')});json(res,200,{status:'Locked',financialStatus:status})}));
app.post('/api/admin/orders/:id/correct',requireStore,auth,role('admin'),asyncRoute(async(req,res)=>{const {pricingId,quantity,reason}=req.body||{};if(!reason||String(reason).trim().length<10)invalid('Admin correction must state a reason of at least 10 characters');if(!Number.isSafeInteger(quantity)||quantity<0)invalid('Quantity must be a non-negative integer');await store.serial(async()=>{const o=await store.find('Orders',req.params.id);if(!o||!['Locked','Finalized'].includes(o.status))invalid('Only locked or finalized orders may use this correction endpoint');const b=(await store.list('Order_Boxes')).find(x=>x.orderId===o.id&&x.pricingId===pricingId);if(!b)invalid('Box selection not found',404);await store.update('Order_Boxes',b.id,{quantity});await store.insert('Order_Adjustments',{id:id('ADJ'),orderId:o.id,field:`quantity.${pricingId}`,previousValue:b.quantity,newValue:quantity,reason,actorId:req.identity.id,createdAt:now()});const f=await financial(o);await store.update('Orders',o.id,{financialStatus:f.financialStatus,updatedAt:now()});await audit(req.identity.id,'CORRECT_LOCKED_ORDER','Order',o.id,b.quantity,quantity,reason)});json(res,200,{corrected:true})}));
app.post('/api/admin/orders/:id/financial-approve',requireStore,auth,role('admin'),asyncRoute(async(req,res)=>{await store.serial(async()=>{const o=await store.find('Orders',req.params.id);if(!o||o.status!=='Locked')invalid('Lock selections before financial approval',409);const f=await financial(o),eligibility=canFinalize(o,f);if(!eligibility.allowed)invalid(eligibility.reason,409);if(f.finalOutstanding>0)invalid('Extra payment must be fully verified before final approval',409);await store.update('Orders',o.id,{status:'Finalized',financialStatus:'Approved',updatedAt:now()});await audit(req.identity.id,'FINANCIALLY_APPROVE_ORDER','Order',o.id,'Locked','Finalized',String(req.body?.reason||''))});json(res,200,{status:'Finalized',financialStatus:'Approved'})}));
app.get('/api/admin/reports',requireStore,auth,role('admin'),asyncRoute(async(req,res)=>{const [customers,payments,orders,groups,transfers]=await Promise.all(['Customers','Payments','Orders','Groups','Transfers'].map(x=>store.list(x)));let customersReport=customers.map(c=>({...c,account:paymentAccount(c,payments)}));let orderReport=await Promise.all(orders.map(async o=>({id:o.id,customerId:o.customerId,status:o.status,financial:await financial(o)})));const groupReport=groups.map(g=>({id:g.id,name:g.name,members:customers.filter(c=>c.groupId===g.id).length,totalMonthlyEmi:customers.filter(c=>c.groupId===g.id).reduce((n,c)=>n+Number(c.emi),0),verifiedCash:payments.filter(p=>p.status==='Verified'&&customers.some(c=>c.groupId===g.id&&c.id===p.customerId)).reduce((n,p)=>n+Number(p.amount),0),transfersConfirmed:transfers.filter(t=>t.status==='Confirmed'&&t.fromId===g.leaderCustomerId).reduce((n,t)=>n+Number(t.amount),0)}));json(res,200,{customers:customersReport,groups:groupReport,orders:orderReport,transfers})}));
app.post('/api/admin/summaries/refresh',requireStore,auth,role('admin'),asyncRoute(async(req,res)=>{const [customers,payments,groups,transfers]=await Promise.all(['Customers','Payments','Groups','Transfers'].map(x=>store.list(x)));const timestamp=now();const summary=customers.map(c=>{let p=paymentAccount(c,payments);return {customerId:c.id,name:c.name,monthlyEmi:c.emi,paidCash:p.paidCash,contributions:p.contributions,bonus:p.approvedBonus,credit:p.availableCredit,remainingCash:p.remainingCash,updatedAt:timestamp}});const groupSummary=groups.map(g=>({groupId:g.id,name:g.name,members:customers.filter(c=>c.groupId===g.id).length,totalMonthlyEmi:customers.filter(c=>c.groupId===g.id).reduce((n,c)=>n+Number(c.emi),0),verifiedCash:payments.filter(p=>p.status==='Verified'&&customers.some(c=>c.groupId===g.id&&c.id===p.customerId)).reduce((s,p)=>s+Number(p.amount),0),transfersConfirmed:transfers.filter(t=>t.status==='Confirmed'&&t.fromId===g.leaderCustomerId).reduce((s,t)=>s+Number(t.amount),0),updatedAt:timestamp}));await store.serial(async()=>{await store.replaceSheet('Customer_Summary',summary);await store.replaceSheet('Group_Summary',groupSummary);await audit(req.identity.id,'REFRESH_SUMMARIES','Reports','',null,{customers:summary.length,groups:groupSummary.length})});json(res,200,{customers:summary.length,groups:groupSummary.length})}));
app.get('/api/admin/settings',requireStore,auth,role('admin'),asyncRoute(async(req,res)=>json(res,200,{windows:await settings(),operationsEnabled:operationsAllowed(),legallyCleared:legallyCleared()})));
app.patch('/api/admin/settings/:window',requireStore,auth,role('admin'),asyncRoute(async(req,res)=>{const key=req.params.window,{live,start,end}=req.body||{};if(!['registration','payment','order'].includes(key)||typeof live!=='boolean'||!/^\d{4}-\d{2}-\d{2}$/.test(start||'')||!/^\d{4}-\d{2}-\d{2}$/.test(end||'')||start>end)invalid('Invalid window configuration');if(live&&!operationsAllowed())invalid('Cannot activate while policy clearance is disabled',423);if(live&&key==='order'&&!legallyCleared())invalid('Cannot activate ordering without legal clearance',423);const config={live,start,end};await store.serial(async()=>{const row=await store.find('Settings','window.'+key,'key');if(row)await store.update('Settings',row.key,{value:JSON.stringify(config),updatedAt:now(),updatedBy:req.identity.id},'key');else await store.insert('Settings',{key:'window.'+key,value:JSON.stringify(config),updatedAt:now(),updatedBy:req.identity.id});await audit(req.identity.id,'WINDOW_CHANGED','Settings',key,'',config)});json(res,200,{window:key,...config})}));
