app.post('/api/admin/refund-reviews',requireStore,auth,role('admin'),asyncRoute(async(req,res)=>{const {paymentId,customerId,reason}=req.body||{};if(!reason||String(reason).trim().length<10)invalid('A written refund review reason is required');if(!await store.find('Payments',paymentId))invalid('Unknown payment',404);await store.serial(async()=>{let review={id:id('RFD'),paymentId,customerId,amount:0,status:'Manual Review Only',reason:String(reason),createdAt:now()};await store.insert('Refunds',review);await audit(req.identity.id,'CREATE_REFUND_REVIEW','Refund',review.id,'',review)});json(res,201,{status:'Manual Review Only',noPaymentInitiated:true})}));
